def verify():
    # Fail-closed, deterministic, integer-only, no imports, no I/O.
    # Returns True only if every required property is exactly verified;
    # any mismatch raises (abort), never returns True.
    W = {
        'encoding': 'size-3-forbidding finite surrogate',
        'graphs': [
            {'name': 'C5_complement', 'n': 5,
             'edges': [(0, 2), (0, 3), (1, 3), (1, 4), (2, 4)],
             'claimed_witness': (0, 2)},
            {'name': 'directed_3_cycle', 'n': 3,
             'directed_edges': [(0, 1), (1, 2), (2, 0)],
             'claimed_witness': (0, 1)}
        ]
    }
    if W['encoding'] != 'size-3-forbidding finite surrogate':
        raise AssertionError('encoding mismatch')
    if len(W['graphs']) != 2:
        raise AssertionError('expected exactly 2 graphs')
    for g in W['graphs']:
        n = g['n']
        edges = g.get('edges', [])
        dedges = g.get('directed_edges', [])
        if not isinstance(n, int) or n <= 0:
            raise AssertionError('bad n')
        if len(edges) + len(dedges) == 0:
            raise AssertionError('no edges given')
        if len(edges) > 0 and len(dedges) > 0:
            raise AssertionError('ambiguous encoding')
        und = len(dedges) == 0
        es = set(frozenset(e) for e in edges) if und else \
             set(tuple(d) for d in dedges)
        if und and any(len(e) != 2 for e in es):
            raise AssertionError('bad edge')
        if not und and any(a == b for a, b in es):
            raise AssertionError('bad directed edge')
        def is_ind(s):
            pairs = [(a, b) for a in s for b in s if a != b]
            if und:
                return all(frozenset(p) not in es for p in pairs)
            return all(p not in es for p in pairs)
        # enumerate ALL subsets; alpha must be exactly 2
        best = 0
        for k in range(n + 1):
            for s in _combs(n, k):
                if is_ind(s) and len(s) > best:
                    best = len(s)
        if best != 2:
            raise AssertionError('alpha %d != 2 in %s' % (best, g['name']))
        # no independent triple (size-3 forbidding)
        for s in _combs(n, 3):
            if is_ind(s):
                raise AssertionError('independent triple in %s' % g['name'])
        # claimed witness must be an independent set of size 2
        w = g['claimed_witness']
        if len(set(w)) != 2 or not is_ind(set(w)):
            raise AssertionError('bad witness in %s' % g['name'])
    return True

def _combs(n, k):
    # exact integer enumeration of k-subsets of {0..n-1}, deterministic order
    out = []
    def rec(start, acc):
        if len(acc) == k:
            out.append(frozenset(acc))
            return
        for i in range(start, n):
            acc.append(i)
            rec(i + 1, acc)
            acc.pop()
    if 0 <= k <= n:
        rec(0, [])
    return out

verify()
